"""Page tokens: opaque, URL-safe strings that mark a position in the feed."""

import base64
import binascii
import json

from activity.store import Event


class InvalidCursor(ValueError):
    pass


def encode(last: Event) -> str:
    """Token for the position just after `last`."""
    payload = json.dumps({"t": last.created_at})
    return base64.urlsafe_b64encode(payload.encode("utf-8")).decode("ascii")


def decode(token: str) -> int:
    try:
        payload = json.loads(base64.urlsafe_b64decode(token.encode("ascii")))
        return int(payload["t"])
    except (binascii.Error, UnicodeError, ValueError, KeyError, TypeError) as exc:
        raise InvalidCursor(f"not a valid page token: {token!r}") from exc

from dataclasses import dataclass


@dataclass(frozen=True)
class Event:
    id: int
    created_at: int  # seconds since the epoch
    kind: str


class EventStore:
    """In-memory event storage."""

    def __init__(self, events: list[Event] | None = None) -> None:
        self._events: list[Event] = []
        for event in events or []:
            self.add(event)

    def add(self, event: Event) -> None:
        if any(existing.id == event.id for existing in self._events):
            raise ValueError(f"duplicate event id {event.id}")
        self._events.append(event)

    def __len__(self) -> int:
        return len(self._events)

    def page(self, after: int | None, limit: int) -> list[Event]:
        """Up to `limit` events in feed order, starting after position `after`
        (None = from the start)."""
        if limit < 1:
            raise ValueError("limit must be >= 1")
        ordered = sorted(self._events, key=lambda e: e.created_at)
        if after is not None:
            ordered = [e for e in ordered if e.created_at > after]
        return ordered[:limit]

